-- 000025_evaluation_reports.sql
-- Evaluation report (评估报告) of the comprehensive-evaluation module
-- (module 4): the aggregated report of one completed drill run. The
-- report is generated by the automatic scoring engine (deterministic
-- formulas over the drill/dispatch records plus the three human scoring
-- sources plus the demo scores of the run metadata) and stored as a
-- snapshot. overall_score is the weighted total; the column type is
-- REAL because every score of the module is rounded to one decimal —
-- the product rule "所有得分四舍五入保留 1 位小数" wins over the INT of
-- the original spec, a conflict pinned by the evaluation_reports card.
-- dimension_scores / indicator_scores / suggestions are the JSONB
-- snapshots of the engine output (dimension_scores = {维度: {score,
-- breakdown}}, indicator_scores = {指标id: {score, auto?, expert?,
-- self_peer?, demo?}}, suggestions = [{dimension, level, text}]). run_id
-- is UNIQUE: at most one report exists per run, regenerating overwrites
-- it in place (id/created_at preserved, updated_at refreshed). The run
-- foreign key cascades, so deleting a run removes its report (the
-- in-memory evaluation report store mirrors this through
-- DeleteReportsByRun, hooked into the drills service run-deletion
-- cascade). created_by defaults to '' and the timestamps are
-- server-maintained, following the repository conventions of the
-- module.

CREATE TABLE IF NOT EXISTS evaluation_reports (
    id               TEXT PRIMARY KEY,
    run_id           TEXT NOT NULL UNIQUE REFERENCES drill_runs(id) ON DELETE CASCADE,
    overall_score    REAL NOT NULL DEFAULT 0,
    dimension_scores JSONB NOT NULL DEFAULT '{}'::jsonb,
    indicator_scores JSONB NOT NULL DEFAULT '{}'::jsonb,
    suggestions      JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_by       TEXT NOT NULL DEFAULT '',
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
